mapper.sql:
p.deleted_at IS NULL
AND p.status = 'PUBLISHED'

  AND (
    p.visibility = 'PUBLIC'

      OR p.author_user_id = #{userId}

  )

mapper.select:
SELECT FROM board_post p JOIN user_account u ON u.user_id = p.author_user_id LEFT JOIN work_item wi ON wi.board_post_id = p.post_id AND wi.status = 'PUBLISHED' LEFT JOIN file_metadata fm ON fm.file_id = wi.file_id AND fm.status = 'ACTIVE' LEFT JOIN team t ON t.team_id = wi.team_id WHERE AND p.category = #{category}
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR wi.title LIKE CONCAT('%', #{keyword}, '%') OR wi.description LIKE CONCAT('%', #{keyword}, '%') OR wi.youtube_title LIKE CONCAT('%', #{keyword}, '%') OR wi.youtube_channel_title LIKE CONCAT('%', #{keyword}, '%') OR wi.youtube_video_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR t.name LIKE CONCAT('%', #{keyword}, '%') )
AND COALESCE(p.free_category, 'FREE') = #{freeCategory}
AND COALESCE(wi.work_type, 'OTHER') = #{workType}
AND EXISTS ( SELECT 1 FROM work_genre wgf WHERE wgf.work_id = wi.work_id AND wgf.genre_id = #{genreId} )
ORDER BY
p.created_at DESC, p.post_id DESC p.like_count DESC, p.created_at DESC, p.post_id DESC p.view_count DESC, p.created_at DESC, p.post_id DESC reactionScore DESC, p.created_at DESC, p.post_id DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO board_post (
  author_user_id, category, free_category, title, content, status, visibility, like_count, review_count, view_count, created_at
) VALUES (
  #{authorUserId}, #{category}, #{freeCategory,jdbcType=VARCHAR}, #{title}, #{content}, #{status}, #{visibility}, 0, 0, 0, NOW()
)

INSERT INTO board_review (
  post_id, author_user_id, parent_review_id, content, status, created_at
) VALUES (
  #{postId}, #{authorUserId}, #{parentReviewId}, #{content}, #{status}, NOW()
)

mapper.select:
SELECT active_yn
FROM board_like
WHERE post_id = #{postId}
  AND user_id = #{userId}

mapper.update:
UPDATE board_like
SET active_yn = #{activeYn},
    updated_at = NOW()
WHERE post_id = #{postId}
  AND user_id = #{userId}

mapper.select:
SELECT like_count
FROM board_post
WHERE post_id = #{postId}

mapper.update:
UPDATE board_post p
SET p.like_count = (
  SELECT COUNT(*)
  FROM board_like bl
  WHERE bl.post_id = #{postId}
    AND bl.active_yn = 'Y'
)
WHERE p.post_id = #{postId}

UPDATE board_post p
SET p.review_count = (
  SELECT COUNT(*)
  FROM board_review br
  WHERE br.post_id = #{postId}
    AND br.status = 'PUBLISHED'
    AND br.deleted_at IS NULL
)
WHERE p.post_id = #{postId}

mapper.select:
SELECT COUNT(*)
FROM board_view_log
WHERE post_id = #{postId}
  AND created_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)


      AND viewer_user_id = #{userId}


      AND viewer_user_id IS NULL
      AND ip_hash = #{ipHash}

mapper.update:
UPDATE board_post
SET view_count = view_count + 1
WHERE post_id = #{postId}

mapper.select:
SELECT p.post_id AS postId, p.title, u.nickname AS authorNickname, wi.work_id AS workId, wi.media_type AS mediaType, COALESCE(wi.work_type, 'OTHER') AS workType, ( SELECT wg.genre_id FROM work_genre wg WHERE wg.work_id = wi.work_id ORDER BY wg.sort_order, wg.genre_id LIMIT 1 ) AS primaryGenreId, ( SELECT g.name FROM work_genre wg JOIN genre g ON g.genre_id = wg.genre_id WHERE wg.work_id = wi.work_id ORDER BY wg.sort_order, wg.genre_id LIMIT 1 ) AS primaryGenreName, wi.youtube_url AS youtubeUrl, wi.youtube_video_id AS youtubeVideoId, wi.youtube_title AS youtubeTitle, wi.youtube_channel_title AS youtubeChannelTitle, wi.youtube_thumbnail_url AS youtubeThumbnailUrl, CASE WHEN wi.representative_image_path IS NOT NULL THEN CONCAT('/api/media/images/work/', p.post_id) ELSE NULL END AS representativeImageUrl, wi.youtube_duration_seconds AS youtubeDurationSeconds, p.like_count AS likeCount, p.review_count AS reviewCount, p.view_count AS viewCount, ROUND((p.like_count * 2) + (p.review_count * 5) + (p.view_count * 0.1), 1) AS reactionScore, CASE WHEN #{currentUserId} IS NULL THEN 0 WHEN EXISTS ( SELECT 1 FROM board_like bl WHERE bl.post_id = p.post_id AND bl.user_id = #{currentUserId} AND bl.active_yn = 'Y' ) THEN 1 ELSE 0 END AS likedByCurrentUser FROM board_post p JOIN user_account u ON u.user_id = p.author_user_id LEFT JOIN work_item wi ON wi.board_post_id = p.post_id AND wi.status = 'PUBLISHED' LEFT JOIN file_metadata fm ON fm.file_id = wi.file_id AND fm.status = 'ACTIVE' WHERE p.category = 'WORK' AND p.status = 'PUBLISHED' AND p.visibility = 'PUBLIC' AND p.deleted_at IS NULL
AND COALESCE(wi.work_type, 'OTHER') = #{workType}
AND EXISTS ( SELECT 1 FROM work_genre wgf WHERE wgf.work_id = wi.work_id AND wgf.genre_id = #{genreId} )
AND p.created_at >= DATE_SUB(NOW(), INTERVAL 7 DAY)
AND p.created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)
ORDER BY p.like_count DESC, p.created_at DESC, p.post_id DESC LIMIT #{limit}
